                moveq   #$C,d2
                moveq   #8,d3
                move.w  (sp)+,d4
                jsr     (SolidObjectFull).l
                jsr     (Animate_Raw).l
                tst.w   x_vel(a0)
                bmi.s   loc_4B8CC
                moveq   #$10,d3                         ; If moving to the right
