                cmpi.w  #$3380,d0
                bhs.w   loc_4B9A8                       ; Reverse direction if edge of screen is hit
                move.w  y_pos(a0),d1
                bsr.w   CNZMinibossTop_CheckHitBase
                bne.w   loc_4B9A8                       ; Reverse direction if miniboss base was hit
                bra.w   loc_4B8F6
