                jsr     CreateChild1_Normal(pc)
                bne.s   loc_4B97E
                tst.w   x_vel(a0)
                bmi.s   loc_4B97E
                bset    #0,render_flags(a1)

loc_4B97E:
                moveq   #$10,d0
                neg.w   x_vel(a0)                       ; Change direction
                bmi.s   loc_4B988
                neg.w   d0

