                rts
; ---------------------------------------------------------------------------

loc_4B9AE:
                move.w  x_pos(a0),d0
                moveq   #8,d1
                neg.w   y_vel(a0)
                bmi.s   loc_4B9BC
                neg.w   d1

loc_4B9BC:
                add.w   y_pos(a0),d1
                cmpi.w  #$3200,d0
                bls.s   locret_4B9A6
                cmpi.w  #$3380,d0
                bhs.s   locret_4B9A6
                cmpi.w  #$300,d1
                blo.s   locret_4B9A6
                cmpi.w  #$3380,d1
                bhs.s   locret_4B9A6
                move.w  d0,(Events_bg+$00).w            ; Move X/Y positions into special variables see above
                move.w  d1,(Events_bg+$02).w
                bsr.w   CNZMiniboss_BlockExplosion
                rts
