                neg.w   x_vel(a0)                       ; If moving in opposite directions, reverse

loc_4BE04:
                tst.w   y_vel(a0)
                bmi.w   loc_4BE10
                moveq   #1,d0                           ; If top is moving downward on collision, set collision flag

locret_4BE0E:
                rts
; ---------------------------------------------------------------------------

loc_4BE10:
                moveq   #0,d0
                rts
; End of function sub_4BDA8

