                cmp.w   d2,d3
                beq.s   loc_53AD0
                bhi.s   loc_53AAA
                swap    d3                              ; If Y distance is closer to object
                clr.w   d3
                divu.w  d2,d3
                tst.w   d0
                beq.s   loc_53A9C
                cmpi.w  #$8000,d2                       ; If Y was closer and Sonic is to right of object
                blo.s   loc_53AEC
                tst.w   d0
                beq.s   loc_53AE8
                bra.w   loc_53AF0
