; ---------------------------------------------------------------------------

loc_53F42:
                addq.b  #1,3(a1)                        ; Add one to counter
                cmp.b   3(a1),d2                        ; Compare with max counter
                bhi.s   loc_53F5C
                move.w  2(a4),d2
                adda.w  d2,a2
                move.l  a2,4(a1)                        ; Load new script after counter has finished
                movea.w (a2),a3
                clr.w   2(a1)

loc_53F5C:
                moveq   #4,d0                           ; Start from the beginning of the rotation
                lea     (a2,d0.w),a4
                rts
; ---------------------------------------------------------------------------

loc_53F64:
